"""Freeze and run V87; only a qualified mean model may proceed to count validation."""
import argparse,gc
import numpy as np
import torch
from threadpoolctl import threadpool_limits
import v87_conditional_adapter as m
from v57_pie import read,write,sha
from run_v35_v36 import contexts,key
from evaluate_v77 import profiles
from audit_transfer_validation import pds

def freeze():
 m.A.mkdir(parents=True,exist_ok=True);assert not (m.A/'plan.json').exists()
 names=['v87_conditional_adapter.py','run_v87_experiment.py','test_v87_adapter.py','audit_v87_experiment.py','inspect_bolero_v87.py','v15_ensemble_methods.py','v62_conserved_response.py','v63_identity_guard.py','fit_v7_response.py','v7_response_methods.py','evaluate_v77.py','audit_transfer_validation.py']
 write(m.A/'plan.json',dict(version=87,primary='conditional25',paper='https://www.biorxiv.org/content/10.64898/2026.10.19.760026v1',inspection_sha256=sha(m.A/'bolero_inspection.json'),mechanism='Independent conditional low-rank adaptation of a frozen source-response neural operator, inspired by BOLERO conditional weight generation. No DNA sequence, ATAC, pretrained BOLERO weights or chromVAR activity is used; not a BOLERO reproduction.',novelty='V14 fitted per-output linear context slopes; V30 STRING-to-source-basis regressions; V35/V36 learned attention/gene decoders; V84 a linear essential-target response operator. Here an MLP generates both low-rank factors for each frozen backbone layer from continuous source and query control-rank features. Actual measured response vectors, not target identity alone, are operator inputs.',sources='Existing validated K562,CD4,H1,HCT116,HEK293T panel responses with bounded90%-dose convention. Whole H1, Orion(both lines), or CD4(all states/donors) excluded before basis, backbone, conditional adapter and null fits.',outputs='Complete-case nonpanel output axis: source NTC CPM finite and>5 and measured in every present source target. Require>=512genes; do not fill absent response values. Present target requires>=100measured outputs. Missing target/source rows omitted. Complete-case masks use all permitted source rows; quantitative fitting uses only240 training targets.',basis='32-component randomized SVD on source fitting-target assay responses log1p(.05CPM*2^LFC)-log1p(.05CPM). Latent RMS scale floor0.1. Deterministic16dim random sketch of centered unit source/query measured expression ranks. Missing query embedding features are centered zero only, >=90%measured query required; no RNA pseudocount. Panel genes excluded from context axes and bases.',model='Frozen-backbone pretraining: residual32->64 GELU->32 MLP, zero-initialized final layer. For each layer add0.1*B(c)A(c), rank4. Each factor generated by48->32 GELU->factor MLP, B final layer zero-initialized. Condition concatenates source16,query16,difference16. No condition-dependent base bias. Every base parameter frozen during adapter fitting and checked exactly.',fit='Directed source pairs only between distinct study groups, same measured target. Pair weights inverse target-count and number of source/destination lines per study. 240/60 deterministic global target split(seed87087); source validation targets excluded from SVD and fitted labels. All100epochs of fullbatch AdamW lr.001 weightdecay.001 gradientclip1, best epoch0..100 chosen by source-target validation normalized coefficient MSE. This is bounded training, not convergence evidence.',controls='constant25: same frozen real backbone and adapter architecture, all conditioner inputs zero, independently optimized. conditional25_shuffled: source target labels independently cyclically shifted by37+11*sourceindex BEFORE basis/backbone/adapter fitting and inference, fully refitted. Same hyperparameters and seeds. All outputs retained, no alternative strength selection.',inference='Pool mapped source latent predictions with exp(2cosine rank-sketch similarity) weights and inverse source-lines/study count; decode fixed basis. Only supported finite positive query outputs proposed. 25% of LFC difference bounded+/-0.5, followed by unchanged80%V66 identity-margin guard. Own LFC always0, emitter handles explicit knockdown. Pre-guard panel effects unchanged; guard/profile closure may change other effect factors.',development='All655 reused public target-context pairs, same truth bank and V66 comparator as V86. Equal study H1/Orion/CD4. Require profile ratio<=.995,worststudy<=1.03,PDSchange>=-.005, beats constant and fully refitted shuffled profile errors. No query-label selection of epochs, architecture or strength.',downstream='Only a passing primary proceeds to unchanged V16 residual10 D3 counts against V66 and both controls, original14targetcohort/seed0; gate as V86, then seed620000 if all pass. D3 is reused, not blind. No cell generation/package otherwise; no automatic upload.',limitations='Only three or four independent training study contexts per outer fold; context is confounded with assay and cannot prove causal response specificity. Actual source response at a target is legitimate evidence; this does not test a never-observed target scenario. Complete-case and low-rank truncation restrict output coverage. Existing V66 mistakes can survive guard.',code_sha256={n:sha(m.ROOT/n) for n in names},source_cache_sha256=sha(m.ROOT/'experiments/v7_multisource_adaptive/analysis/source_cache.npz')))
 print('V87 protocol frozen',flush=True)

def prepare():
 m.check();folder=m.A/'predictions';folder.mkdir(exist_ok=True)
 for ctx in contexts():
  name=ctx['family'];out=folder/(name+'.npz');assert not out.exists();p=m.ROOT/'experiments/v66_assay_strength/analysis/predictions'/(name+'.npz');assert sha(p)==read(p.with_suffix('.json'))['sha256']
  with np.load(p,allow_pickle=False) as z:q=z['query'].copy();bulk=z['bulk'].copy();base=z['assay75'].copy()
  pred,tr=m.predict(q,base,bulk,key(name));np.savez_compressed(out,query=q,bulk=bulk,v66=base,**pred);write(out.with_suffix('.json'),dict(sha256=sha(out),V66_source_sha256=sha(p),outer=key(name),trace=tr,plan_sha256=sha(m.A/'plan.json')));print('V87 predicted',name,{k:t.get('changed_targets',0) for k,t in tr.items()},flush=True);gc.collect()

def means():
 m.check();d=m.data();genes=d['genes'];own=np.array([list(genes).index(t) for t in d['targets']]);arms=('v66',)+m.ARMS;records=[]
 for ctx in contexts():
  name=ctx['family'];p=m.A/'predictions'/(name+'.npz');assert sha(p)==read(p.with_suffix('.json'))['sha256']
  with np.load(p,allow_pickle=False) as z:pred={a:profiles(z[a],z['bulk'],own) for a in arms}
  tp=m.ROOT/'experiments/v77_common_response/analysis/truth_bank'/(name+'.npz');assert sha(tp)==read(tp.with_suffix('.json'))['sha256']
  with np.load(tp,allow_pickle=False) as z:bank={k:z[k].copy() for k in z.files}
  scores={};axis=bank['measured']&~np.isin(genes,d['targets']);errors={}
  for arm in arms:
   err=[]
   for i,ti in enumerate(bank['target_indices']):
    mask=bank['measured'].copy();mask[own[ti]]=False;err.append(float(np.mean((pred[arm][ti,mask]-bank['truth'][i,mask])**2)))
   errors[arm]=err;scores[arm]=dict(profile_MSE=float(np.mean(err)),pds=pds(pred[arm][bank['target_indices']][:,axis],bank['truth'][:,axis],bank['control'][axis]))
  records.append(dict(source=name,study=key(name),pairs=len(bank['target_indices']),targets=bank['target_indices'].tolist(),profile_errors=errors,scores=scores));print('V87 means',name,{a:round(scores[a]['profile_MSE']/scores['v66']['profile_MSE'],6) for a in m.ARMS},flush=True)
 summary={};studies={}
 for arm in m.ARMS:
  studies[arm]={}
  for group in ['H1','Orion','CD4']:
   rows=[r for r in records if r['study']==group];studies[arm][group]=dict(profile_ratio=float(np.mean([r['scores'][arm]['profile_MSE']/r['scores']['v66']['profile_MSE'] for r in rows])),pds_change=float(np.mean([r['scores'][arm]['pds']-r['scores']['v66']['pds'] for r in rows])))
  summary[arm]={k:float(np.mean([s[k] for s in studies[arm].values()])) for k in ['profile_ratio','pds_change']}
 s=summary['conditional25'];checks=dict(profile=s['profile_ratio']<=.995,worst_study=max(r['profile_ratio'] for r in studies['conditional25'].values())<=1.03,pds=s['pds_change']>=-.005,beats_constant=s['profile_ratio']<summary['constant25']['profile_ratio'],beats_shuffle=s['profile_ratio']<summary['conditional25_shuffled']['profile_ratio'])
 result=dict(summary=summary,studies=studies,records=records,checks=checks,passes=all(checks.values()),pairs=sum(r['pairs'] for r in records),scope='655 reused public pairs; source target-held validation selects training epochs, never these recipient outcomes. Raw public metrics, not anchored competition scores.');write(m.A/'mean_results.json',result);print('V87 final',summary,checks,flush=True)
 if not result['passes']:write(m.A/'release_decision.json',dict(primary='conditional25',mean_gate_passed=False,count_test_run=False,new_upload_generated=False,best_published='V66/V82',reason='Prespecified public mean gate failed; no count decoding or new package.',mean_results_sha256=sha(m.A/'mean_results.json')))

if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('stage',choices=['freeze','fit','prepare','means']);p.add_argument('--outer',choices=['H1','Orion','CD4']);p.add_argument('--shuffled',action='store_true');a=p.parse_args();torch.set_num_threads(2)
 with threadpool_limits(limits=2):{'freeze':freeze,'fit':lambda:m.fit(a.outer,a.shuffled),'prepare':prepare,'means':means}[a.stage]()
